/** void ClearScheduledBgCopiesToVram(void) */
export function ClearScheduledBgCopiesToVram(): any {
  memset(sScheduledBgCopiesToVram, 0, 0);
}

/** void ScheduleBgCopyTilemapToVram(u8 bgId) */
export function ScheduleBgCopyTilemapToVram(bgId: any): any {
  sScheduledBgCopiesToVram[bgId] = TRUE;
}

/** void DoScheduledBgTilemapCopiesToVram(void) */
export function DoScheduledBgTilemapCopiesToVram(): any {
  if (sScheduledBgCopiesToVram[0] == TRUE)
      {
          CopyBgTilemapBufferToVram(0);
          sScheduledBgCopiesToVram[0] = FALSE;
      }
      if (sScheduledBgCopiesToVram[1] == TRUE)
      {
          CopyBgTilemapBufferToVram(1);
          sScheduledBgCopiesToVram[1] = FALSE;
      }
      if (sScheduledBgCopiesToVram[2] == TRUE)
      {
          CopyBgTilemapBufferToVram(2);
          sScheduledBgCopiesToVram[2] = FALSE;
      }
      if (sScheduledBgCopiesToVram[3] == TRUE)
      {
          CopyBgTilemapBufferToVram(3);
          sScheduledBgCopiesToVram[3] = FALSE;
      }
}

/** void ResetTempTileDataBuffers(void) */
export function ResetTempTileDataBuffers(): any {
  let i: any = null;
      for (i = 0; i < ARRAY_COUNT(sTempTileDataBuffer); i++)
          sTempTileDataBuffer[i] = NULL;
      sTempTileDataBufferIdx = 0;
}

/** bool8 FreeTempTileDataBuffersIfPossible(void) */
export function FreeTempTileDataBuffersIfPossible(): any {
  let i: any = null;

      if (!IsDma3ManagerBusyWithBgCopy())
      {
          if (sTempTileDataBufferIdx)
          {
              for (i = 0; i < sTempTileDataBufferIdx; i++)
                  FREE_AND_SET_NULL(sTempTileDataBuffer[i]);
              sTempTileDataBufferIdx = 0;
          }
          return FALSE;
      }
      else
      {
          return TRUE;
      }
}

/** void DecompressAndLoadBgGfxUsingHeap(u8 bgId, const void *src, u32 size, u16 offset, u8 mode) */
export function DecompressAndLoadBgGfxUsingHeap(bgId: any, src: any, size: any, offset: any, mode: any): any {
  let sizeOut: any = null;
      let ptr: any = malloc_and_decompress(src,sizeOut);
      if (!size)
          size = sizeOut;
      if (ptr)
      {
          let taskId: any = CreateTask(task_free_buf_after_copying_tile_data_to_vram, 0);
          gTasks[taskId].data[0] = copy_decompressed_tile_data_to_vram(bgId, ptr, size, offset, mode);
          SetWordTaskArg(taskId, 1, ptr);
      }
}

/** void task_free_buf_after_copying_tile_data_to_vram(u8 taskId) */
export function task_free_buf_after_copying_tile_data_to_vram(taskId: any): any {
  if (!CheckForSpaceForDma3Request(gTasks[taskId].data[0]))
      {
          Free(GetWordTaskArg(taskId, 1));
          DestroyTask(taskId);
      }
}

/** u16 copy_decompressed_tile_data_to_vram(u8 bgId, const void *src, u16 size, u16 offset, u8 mode) */
export function copy_decompressed_tile_data_to_vram(bgId: any, src: any, size: any, offset: any, mode: any): any {
  switch (mode)
      {
          case 0:
              return LoadBgTiles(bgId, src, size, offset);
          case 1:
              return LoadBgTilemap(bgId, src, size, offset);
          default:
              return -1;
      }
}

/** void SetBgTilemapPalette(u8 bgId, u8 left, u8 top, u8 width, u8 height, u8 palette) */
export function SetBgTilemapPalette(bgId: any, left: any, top: any, width: any, height: any, palette: any): any {
  let i: any = null;
      let j: any = null;
      let ptr: any = GetBgTilemapBuffer(bgId);

      for (i = top; i < top + height; i++)
      {
          for (j = left; j < left + width; j++)
          {
              ptr[(i * 32) + j] = (ptr[(i * 32) + j] & 0xFFF) | (palette << 12);
          }
      }
}

/** void CopyToBufferFromBgTilemap(u8 bgId, u16 *dest, u8 left, u8 top, u8 width, u8 height) */
export function CopyToBufferFromBgTilemap(bgId: any, dest: any, left: any, top: any, width: any, height: any): any {
  let i: any = null;
      let j: any = null;
      let src: any = GetBgTilemapBuffer(bgId);

      for (i = 0; i < height; i++)
      {
          for (j = 0; j < width; j++)
              dest[(i * width) + j] = src[(i + top) * 32 + j + left];
      }
}

/** void AddValToTilemapBuffer(void *ptr, int delta, int width, int height, bool32 isAffine) */
export function AddValToTilemapBuffer(ptr: any, delta: any, width: any, height: any, isAffine: any): any {
  let i: any = null;
      let area: any = width * height;
      if (isAffine == TRUE)
      {
          let as8BPP: any = ptr;
          for (i = 0; i < area; i++)
              as8BPP[i] += delta;
      }
      else
      {
           
          let as4BPP: any = ptr;
          for (i = 0; i < area; i++)
              as4BPP[i] = (as4BPP[i] & 0xFC00) | ((as4BPP[i] + delta) & 0x3FF);
      }
}

